CREATE TABLE voice_segments (id TEXT PRIMARY KEY NOT NULL,project_id TEXT NOT NULL,scene_version_id TEXT NOT NULL,audio_asset_id TEXT NOT NULL,segment_index INTEGER NOT NULL CHECK(segment_index>=0),text TEXT NOT NULL CHECK(length(text)>0),start_ms INTEGER NOT NULL CHECK(start_ms>=0),end_ms INTEGER NOT NULL CHECK(end_ms>start_ms),alignment_json TEXT NOT NULL CHECK(json_valid(alignment_json)),UNIQUE(scene_version_id,segment_index),FOREIGN KEY(scene_version_id,project_id) REFERENCES scene_versions(id,project_id) ON DELETE RESTRICT,FOREIGN KEY(audio_asset_id,project_id) REFERENCES assets(id,project_id) ON DELETE RESTRICT);
